package com.aig.renderer.unity.api
import kotlin.math.*
class StockRemovalGrid(val nx:Int=24,val ny:Int=16,val widthMm:Double=120.0,val depthMm:Double=80.0,val topMm:Double=20.0){private val h=DoubleArray(nx*ny){topMm};@Synchronized fun reset(){java.util.Arrays.fill(h,topMm)};@Synchronized fun snapshot():DoubleArray=h.copyOf();fun centerX(ix:Int)=-widthMm/2.0+(ix+0.5)*widthMm/nx;fun centerY(iy:Int)=-depthMm/2.0+(iy+0.5)*depthMm/ny;@Synchronized fun cutSegment(x0:Double,y0:Double,z0:Double,x1:Double,y1:Double,z1:Double,toolDiameterMm:Double){val len=hypot(x1-x0,y1-y0);val steps=max(1,ceil(len/max(0.5,toolDiameterMm/5.0)).toInt());val radius=toolDiameterMm/2.0;for(s in 0..steps){val t=s.toDouble()/steps;val x=x0+(x1-x0)*t;val y=y0+(y1-y0)*t;val z=(z0+(z1-z0)*t).coerceIn(0.0,topMm);for(iy in 0 until ny)for(ix in 0 until nx){val dx=centerX(ix)-x;val dy=centerY(iy)-y;if(dx*dx+dy*dy<=radius*radius){val i=iy*nx+ix;if(z<h[i])h[i]=z}}}};@Synchronized fun removedVolumeMm3():Double{val area=(widthMm/nx)*(depthMm/ny);return h.sumOf{(topMm-it)*area}}}
data class CutPoint(val x:Double,val y:Double,val z:Double)
